) AS (
  VALUES 
    (390::BIGINT, 'De fijo meta con el, es muy buena gente, en informes y reportes siempre pone 100, hace examenes pero no son imposibles, y explica muy bien, da instrucciones claras y siempre dispuesto a ayudar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'ce0997d9b6ced4ba77aaa247d405d820ae64c26b56d5fbba9a6a21bda433d333'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'Es buena nota, en las clases explica bien y las instrucciones son claras. Los informes y cuestionarios pone 100 a TODO. Entonces uno solo pierde puntos en los exámenes que tampoco son tan complicados. La verdad muy recomendado. No se atreva a mencionar a Laura Fernandez o Pilar Cisneros.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'c435bcaabe03273ca5debaf0ee65af69e381e19ed89a0c9a006bf5624d654dbe'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'no explica nada en clase y cuesta que responda preguntas del lab. ademas deja demasiados trabajos por semana para la cantidad de creditos. No recomendado.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, '27fab86aed4c9da8027ec4ae5adf05afce40bb3a46f481add7a3d6b937ba8b92'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'Malísimo. La clase es básicamente verlo sentado en el escritorio y escucharlo leer una presentación. Califica normal, pero hay que ser autodidacta para aprender. Mejora un poco cuando hace prácticas, porque ahí si se pone de pie.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-11-30T00:00:00+00:00'::TIMESTAMPTZ, '3ff10562361d1ca494a5b63bb4d36a7921917201b4175ad5b883982dc82ca528'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'El profe es lento para explica que a veces las clase se hacen largas y aburridas, pero cuando se pone a resolver ejercicios uno comprende mejor el tema y lo deja una listo para el examen y es muy tranquilo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2025-10-23T00:00:00+00:00'::TIMESTAMPTZ, '2dea0a494f6f8c5b591284c5cda3274fee6d3dc4c7044a9d0563cbee15441df8'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Es buen profe, en veces se confunde un poco y al inicio la clase puede ser un poco aburrido por la materia. Pero en general le interesa que el estudiante aprenda y es super buena persona.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-12-17T00:00:00+00:00'::TIMESTAMPTZ, '7ad66fcfb25f8bfafbc704ac0d21b5ed54bb69fe8751f09113a777d0436a7ee3'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Cuando le hacen preguntas a veces no recuerda conceptos y se devuelve en las diapositivas para ver que era, no hace prácticas, solo enseña ejercicios y deja que lo hagamls por nuestra cuenta no las resuelve, llega tardísimo a leer diapositivas, aunque es buena nota como persona pero como profe NO'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'f122b9fb696045d337e4d225a0ae8a4470c3033ced54d767a09ae9957c6e2fa5'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'El profesor es muy buena persona y tiene la voluntad de ayudar, pero nada más, ya que no maneja bien la materia y solo lee las presentaciones, no hace ejercicios y los que hace son los fáciles que ya incluyen las presentaciones, así que prepárese para ver las clases de JJ en YT, entender por cuenta'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd26fba5b76d7d3477ebce9bd63b5f980bdf5e2a104b40dc85030905bcc4a916a'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'La verdad sabe muchísimo, pero para intro a electro cuesta mucho que ayude, es difícil encontrarlo por el seslab, y cuando le pide ayuda casi que tiene que resolverlo solo con Tinkercad. Los materiales que utiliza están bastante desactualizados, es un 50/50 matricular con él'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'a9ba306b9a9fec7724a587b530c091873101b63b13a530fcc117303bb2031ecf'::TEXT, ARRAY[1255]::BIGINT[]),
    (390::BIGINT, 'Excelente profesor, brinda apoyo y es flexible si se requiere en general busca que el estudiante aprenda y trabaje, es complicado hallarlo por el SesLab y no siempre lo que pide es claro que se sale adelante si usted lo busca y se mueve a hacer las cosas. Busque un buen compañero sino la cosa es fea'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b26fdb8cdf6dc95f3b88c3395e3c64c57870d0a70d3e50aae98525883e095da2'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'A pesar del que el curso es muy introductorio las clases con el profe son entretenidas, es tuanis y no es muy exigente mientras trabajes, lo recomiendo bastante'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f1a3a35ab6526d99bd8d65b5823bf472daf50e860944576ce92a9212906eace0'::TEXT, ARRAY[1252]::BIGINT[]),
    (390::BIGINT, 'Excelente profesor y persona, deja muchos trabajos los cuestionarios e informes, pero son algo fáciles, es importante buscar un buen compañero de laboratorio, es muy amigable se le entiende a la perfección si no explica las veces necesarias, tarda en calificar pero eso es por el seslab'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '50232c1eae7df8c7fa77e083847a37b9b7d467cafe9ba0674b655edbf66abc24'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'Profesor sabio, sabe lo que enseña. Ayuda a los estudiantes y es amigable. Es estrícto con los reportes, pero son fáciles. No tengo muchas quejas, en realidad hizo todo bien. Felicidades! Como recomendación, buscar un buen compaleñero de lab antes de iniciar el semestre.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'dc571f8e4023949fd71bab3d8dbc3d8ab08c6b3bdf78dd4da4a97af09125ff8a'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'El profe es bueno en general. Se toma en serio sus clases y hay reportes y pre-reportes cada semana lo cual puede ser un poco tedioso, no califica los reportes al día, pero en general ayuda ha aprender bastante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3af8b31c0f6ba0802331ae8c2976578ff11aedb1169c24e050be10f16d76ecc4'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'El ambiente en la clase es muy bueno. Todos los trabajos los deja en un grupo que eligen al inicio del semestre, casi que deja un trabajo por semana. Es muy vacilón, súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '171c54b8eafcee834637bee768614ca54c0e2940c86e1b9d8adf8022629431e1'::TEXT, ARRAY[1252]::BIGINT[]),
    (390::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2024-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'e2e37794ab40abbae5c9842b2d86b13dd9259520e385c4e24e7ef054a2ece1c0'::TEXT, ARRAY[1255]::BIGINT[]),
    (390::BIGINT, 'Es amable, atiende dudas, brinda tiempo extra para los trabajos, da retroalimentación al final del curso uno a uno. Sin embargo, pasa un poco ocupado por lo que se atrasa con las revisiones y dedica poco tiempo a los temas del curso durante las clases y habla muuuuucho de temas no relacionados.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'e6cd01444687f30b2ebef58e5d3323d40c8596bb67690696b04b1c943ad4a5a3'::TEXT, ARRAY[1329]::BIGINT[]),
    (390::BIGINT, 'El curso en si es fácil, es buena gente, dura bastante en calificar, muchos proyectos, pero es interesante y divertido, ayuda bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, '26f9735b3198cd0dcf05d19ce0caa892e7e80ee0e7cc6668abaec3c6702e3d18'::TEXT, ARRAY[1252]::BIGINT[]),
    (390::BIGINT, 'A veces se atrasa en corregir los avances pero es justo y da más tiempo. Siempre es muy amable y dispuesto a ayudar a que uno mejore y tenga un buen anteproyecto. Toma lista, aunque sea virtual, y en cada sesión se hacen trabajos, hágalos a conciencia y los avances le serán faciles de hacer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1c4441fd1fb92da6abc400fcdced353553915e8be9d1124b5035ac1ec6d0103a'::TEXT, ARRAY[1329]::BIGINT[]),
    (390::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-06T00:00:00+00:00'::TIMESTAMPTZ, '73a70771c8d547068b2be3157e81d0d9dc87b40ba954106d5c2935d831ae70d9'::TEXT, ARRAY[1252]::BIGINT[]),
    (390::BIGINT, 'No explica de la mejor manera, los informes son muy largos, y las instrucciones confusas. Califica normal, pero entrega los notas de los informes al puro final, por lo que no hay retroalimentación. En general no lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, '947e5ec1877fb7132cd3dbc630be740958e71afbc8e394d0506769f07ad32460'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Buen profesor. Aclara dudas, explica bien lo que se va a hacer en cada lab y en general, es una excelente opción para llevar el curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '28a8e8d781eb1cd4441ac2ab16b49c889a693bc843d50a41cd738d946a813b37'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Es buen profesor, es muy paciente e intenta dejar claro todos puntos de los informes a realizar. En las sesiones presenciales ayuda al estudiante pero es importante repasar el procedimiento a realizar en el lab, porque el tiempo importa. Es buena opción.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'd4d3e0ad9e535d525f44b36e9a90102492d22fa7b4b887eba140f6afb3415eff'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'No es complicado, pone proyectos pequeños semanales que están relacionados con hacer experimentos o aparatos con materiales caseros. Si no puede entregar un proyecto, te deja entregarlo la próxima semana.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd11137f3f54df1fc0d2e5f4f24262836bf3d0b928b76d8ddcb111be27999fa34'::TEXT, ARRAY[1252]::BIGINT[]),
    (390::BIGINT, 'El curso por la virtualidad fue un poco desordenado, ya que se abusaron de las simulaciones y los informes en IEEE largos y a veces confusos. El profe es tuanis, califica normal. El curso no me gustó porque los informes estaban muy largos, a veces de días.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '68ace5fca00ccd14d36e0869e46389be2181228cb72aa8751d6e3c87b1951da6'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Buena nota, aunque me pareció muy ogro al principio, cualquier duda por mas básica que sea se sienta a explicarte, es de los profes que les interesa que el estudiante aprenda, pero eso si, tiene que haber compromiso con el curso y no ser un vagazo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '0f3ac22678b9b6fdaa5817ef01da165d752521702dd212392764a8020c5362ad'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'El se preocupa mucho por que los anteproyectos esten bien elaborados. Saca el tiempo para dar retroalimentacion uno a uno y es muy paciente. Califica suave. Lo unico malo es que sus clases no son provechosas con los trabajos grupales que deja y es una clase larga que podria resumirse bastante'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '38d30b559b0c2409172c14d18aec8d8910ff2b866856c64485acedbae03ec9a7'::TEXT, ARRAY[1329]::BIGINT[]),
    (390::BIGINT, 'Saca el tiempo para evacuar dudas y ayudar. Buena comprensión con el estudiante en la situación del Covid. Clase llevadera pero a veces extensa.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '7f6376a93e56556c391a66c93218a7ad047300e944a06854f7d75641b845ee1d'::TEXT, ARRAY[1329]::BIGINT[]),
    (390::BIGINT, 'Es excelente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '1a8cbc582dc90e06c093ed8ca1ad4aed87f94111c13163f2b776eeae69ea7de8'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Es el profe para el curso, me ayudo montones para formular el proyecto'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'a8d36d80e568fa2cf53ff539a36478e7ddaf55342adc930709d1deee5851bcbd'::TEXT, ARRAY[1329]::BIGINT[]),
    (390::BIGINT, 'Es muy perfeccionista, ayuda mucho y tiene paciencia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2020-05-26T00:00:00+00:00'::TIMESTAMPTZ, '0b46448f837fe7534efa0a3f73b5ac4092f7d1c1bf43813a0523a56bb2f3357d'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'Recomendado para labs, el mae ayuda y no es muy estricto. No es de los mejores profes de electrónica, pero es muy buena nota. Para cursos teóricos, no promete'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'd8a0e3813fcff38e7b64aa27c575ac989aaf386061d5511feb9ef059e8a954b3'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'Siempre se acerca a ayudar cuando uno se lo pide y no le hace mala cara, muy pura vida. Hay que hacer una bitácora para cada lab y hace quiz sobre la investigación previa todas las semanas, pero son súper fáciles.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-30T00:00:00+00:00'::TIMESTAMPTZ, '878c917eacedd70ce834a303bbb7832c7c4ff335f17dfa1cc4d26d1ca0d48e66'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'Si quiere pasar el curso fácil no meta con él, sin embargo se aprende bastante pero hay que trabajar de igual forma a diferencia de con otros profesores. Siempre busca dar opciones para no joderlo a uno y ayudarle lo más posible.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'f57b37d5fe933c6a79fbd7bf104e1589cecca96ecfc88f4a9c671f9652ca70cc'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Dio clases de control solo una semana (las otras semanas dio Meza) pero con eso fue suficiente para demostrar que NO SABE NADA DE CONTROL. Es muy inseguro. No se le puede dar cursos avanzados a gente así. Creo que el va a dar control solo, le recomiendo que no lo haga, meta con interiano.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2019-11-14T00:00:00+00:00'::TIMESTAMPTZ, '3a0f2cdd8d7849925b7e86c38dc226b785f85d45ba2a3452f061ab7f45767d77'::TEXT, ARRAY[1319]::BIGINT[]),
    (390::BIGINT, 'La verdad es que el profe es muy tuanis y cuenta varas graciosas de cuando él estaba en la U, pero como profe no sirve. Aparte de que la materia de activos es pesada, el mae no maneja los conceptos para nada, habla demasiado bajo y solo llega a leer presentaciones.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9d40f1fa71d4fd5c2c83a5cd7185c129ce884bc10abc732e0b9ac773afc97f8a'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Muy buen profe, lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'b750b8a831b5a52d22b69dfec93ef9643d36827c329a1075f085ec073ad53952'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Antes de cada lab se debe realizar un informe que incluye investigación y repasar el procedimiento, hace quiz casi todas las semanas. Ante cualquier duda se acerca a ayudar. Es un profe pura vida!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f7cf9b1715ff7e870d6d99354f367426366c4208a9425c4f5d6e77075dc14f1f'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-04T00:00:00+00:00'::TIMESTAMPTZ, '777d2d4cf3e248269818ea690310868437a28c2891b9f1949bc9f16b66410c71'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'El profe casi no explica, hay temas que los da por vistos, si quiere las cosas fáciles llévelo con él porque casi que regala la nota, pero no se aprende, hay que estudiar por aparte.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'b8e93f60c5a8028a5077f7b45d4c01e1091dc22c097e9b9afbc7d75da87522df'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Es buena gente, da bien la clase, hace tareas y las prácticas y ejemplos son exámenes viejos. En términos generales es buen profe se preocupa por que uno aprenda, pero puede mejorar, lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'af975e034e5e99e40b7077061eaad55f7ee22af1b525635c946fbc6ed255765e'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Ayuda mucho. Los laboratorios son fáciles y si se necesita ayuda él la proporciona. Califica suave, hay que hacer bitácora, papers y una investigación. Exámenes muy fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '756ec62a3e51b8003931365421984a1196c0dc759267e580bfcdf2fc07c15e21'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Es muy pura vida! Hace exámenes muy fáciles, y le ayuda a uno en todo lo que ocupe, le interesa que uno aprenda'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '73a1aad8a1a278af5e72f8324b363e6f08592e3b77a0fa5ca407156450426192'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Es muy pura vida, tiene ese tacto humano y se interesa por que uno aprenda, si es mucha teoría pero lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-11-08T00:00:00+00:00'::TIMESTAMPTZ, '0f0feb550c3c046bb4ef55b2d57fc3be77cf3da04f8d03939d5d1b7f1da7e6f1'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Para lab es muy bueno, los exámenes son fáciles, solo hay que ponerle un poco a los paper que se hacen al final de semestre'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-31T00:00:00+00:00'::TIMESTAMPTZ, '3600fc308122860dab6fe2344b8ad7cca3040f6609f03cfcfa82d4ae90953a56'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Es probablemente el profesor más malo de la Escuela, no se entiende nada, no explica bien, el mismo no comprende la materia. Nunca será una opción'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'a462977e605383f65d4474bf75d26ec1c66d9176db319026cdee18c0c0efba64'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Excelente profesor, explica muy bien la materia y deja muy claro conceptos y fórmulas. Es una lástima que poca gente vaya a su clase. Resuelve dudas y deja bastante práctica . Eso sí, es necesario leer también los libros y scripts antes de ir a lecciones'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-10-07T00:00:00+00:00'::TIMESTAMPTZ, '1d464a2dc91c2ab1a73c7091207797c09f9761cc0467a2b343e859aaeaa00d55'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'El curso tiene mucha teoría y poca practica, el profesor se espera, pero la teoría prefiero tratarla yo en casa'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9a4b129699ea008d101901a1d6590b8d9cdc024d1b6cd8b01f2aeb6bd86fbf58'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Para laboratorio no está mal. Atiende las dudas en clase y hace las evaluaciones necesarias. Es comprensivo con los estudiantes aunque el semestre que llevé tenía sobrecarga laboral y eso fue un problema, pero por lo demás está bien'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e0b8816a749a26ab81fc16bf9f65ebed10aa9e23ab13a8f76bbf8dabe279c2ed'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Es una embarcada, NUNCA meta un curso con el, no sabe nada, lee presentaciones, siempre esta cansado y cancela clases.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '11ae5996e927c36bba8853cdc72db67a80a05a00f0a118f1ae2b3f928bde146f'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Un profe muy buena nota. Ayuda y le explica a uno bastante bien lo básico e inte ha que uno de verdad aprenda. Si edta pegado le ayuda. Exámenes fáciles. Se escribe bastante por la bitácora y los quices son de la bitácora'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5547e174c661316e123368ec984d727983da2030ee83806623df4d138925b6dc'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'El curso se pasa muy fácil con él, pero no sirve para explicar. Cancela mucho clases, da 30 minutos de clase y sale. Después se queja que no le da chance para dar toda la materia, que no tiene tiempo ni para calificar.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4ceaf86ff0aa6a136c2dab1250be71253c69a98db42afada5cb81a1be772c4ab'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'No sabe explicar la materia ni atender dudas, ir clases es ir escuchar que lea la presentación y los scripts. Dura toda la vida entregado los exámenes. Se aprende más leyendo el libro que con este profe.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8fd062d64b42eb9f55d988d770a791ec5db00edfed2db1b99d8f7f383f06424f'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'No domina para nada la materia del curso, su clase es ir a escucharlo leer textual el script. No sabe responder las dudas, no hace ejemplos de nada. Los exámenes los califica duro y dura toda la vida entregándolos.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '6f783ee5e05ad72302eaeb7ad1c6345541fb44dd933de693fa6c7ee988c9147d'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Pasé, es todo lo que puedo decir'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e2662138a791f4cfdba1fa789cc75df27a828951fac346ad3fd566047c1e8ab6'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'El profe es buena gente y si le preguntas algo buscara la forma de responder aunque se enrede un poco a veces. Para laboratorio trabaja con bitacora a mano así que hay que sacar tiempo para hacerla, en general la dificultad de los trabajos y los examenes se apegan al peso de 1 credito.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '83501d5e368c3996507ceb878d24119be1468d42219843cff719944f276a9d99'::TEXT, ARRAY[1261]::BIGINT[]),
    (390::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'c17d657c0219a33ccd00e1a477b6e48245399c05b7a4b2d1a42f35850be9885c'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Este profe es muy buena persona y siempre atiende dudas, el problema es que casi nunca tenía la materia clara (al menos para este curso). En las clases solo llega a pasar la presentación y a leer el script, se enreda resolviendo ejercicios. No lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-21T00:00:00+00:00'::TIMESTAMPTZ, '237411e6a3d44b54a66706788eef865e3954cae5bc12b0c2f11f5bd53aa6a49f'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-11T00:00:00+00:00'::TIMESTAMPTZ, 'f1424047d1f4c01c6ac90a4f8c012f552a3d619e65d887fd0dac665faa583470'::TEXT, ARRAY[1256]::BIGINT[]),
    (390::BIGINT, 'Primera vez que daba el curso, algunas cosas puntuales no las tenía muy claras. Explica bien, atiende dudas y se interesa por el buen aprendizaje.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '842d1fb89d76b7b8b2b0d0c1fcbfb03903f48e8837125f3bf938ab62eb1605a2'::TEXT, ARRAY[1267]::BIGINT[]),
    (390::BIGINT, 'Muy buen profe, clases muy amenas y sabe mucho, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-09-21T00:00:00+00:00'::TIMESTAMPTZ, '95a426f051f815acc949c91b6a52e6f16ed5d538ceca960ae3f58c48bc502c10'::TEXT, ARRAY[925]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
